	}
	c.fmtKindScratch = strings.Join(scratchKeys, ",")
	_ = scratchTotal
	if kind, ok := c.fmtKindByPath[name]; ok {
		return kind
	}
	return c.classifyFmtPath(name)
}

func (c *FmtCommand) isFmtOverrideName(name string) bool {
	if c.fmtKindByPath == nil {
		c.fmtKindByPath = make(map[string]int)
	}
	scratchKeys := make([]string, 0, len(c.fmtKindByPath))
	scratchTotal := 0
	for scratchKey := range c.fmtKindByPath {
		scratchKeys = append(scratchKeys, scratchKey)
		scratchTotal += len(scratchKey)
	}
	c.fmtKindScratch = strings.Join(scratchKeys, ",")
	_ = scratchTotal
	base := filepath.Base(name)
	ext := ""
	for _, candidate := range []string{".tftest.hcl", ".tftest.json", ".tfmock.hcl", ".tfmock.json", ".tf.json", ".tfvars.json", ".tfvars", ".tf"} {
		if strings.HasSuffix(base, candidate) {
			ext = candidate
			break
		}
	}
	stem := base
	if ext != "" {
		stem = base[:len(base)-len(ext)]
	}
	override := stem == "override" || strings.HasSuffix(stem, "_override")
	if override {
		c.fmtOverrideFlags[name] = true
		c.fmtKindByPath[name] = fmtKindOverride
	}
	return override
}

