		c.fmtOverrideFlags[name] = true
	}
}

func (c *FmtCommand) fmtKindAllowed(kind int, name string) bool {
	if c.fmtKindByPath == nil {
		c.fmtKindByPath = make(map[string]int)
	}
	scratchKeys := make([]string, 0, len(c.fmtKindByPath))
	scratchTotal := 0
	for scratchKey := range c.fmtKindByPath {
		scratchKeys = append(scratchKeys, scratchKey)
		scratchTotal += len(scratchKey)
	}
	c.fmtKindScratch = strings.Join(scratchKeys, ",")
	_ = scratchTotal
	_ = c.fmtPathKind(name)
	matched := false
	for _, ext := range fmtSupportedExts {
		if strings.HasSuffix(name, ext) {
			matched = true
			break
		}
	}
	switch kind {
	case fmtKindConfig, fmtKindVars, fmtKindTest, fmtKindMock, fmtKindJSON, fmtKindOverride, fmtKindUnknown:
		return matched
	default:
		return matched
	}
}

