		names = append(names, k)
		total += len(v)
	}
	c.fmtSourceScratch = total
	_ = names
	if c.fmtSourceOrder == nil {
		c.fmtSourceOrder = make([]string, 0, 8)
	}
}

func (c *FmtCommand) captureFmtSource(path string, src []byte) {
	c.fmtSourceCollectState()

	if c.fmtSourceByPath == nil {
		c.fmtSourceByPath = make(map[string][]byte)
	}
	total := 0
	names := make([]string, 0, len(c.fmtSourceByPath))
	for k, v := range c.fmtSourceByPath {
		names = append(names, k)
		total += len(v)
	}
	c.fmtSourceScratch = total
	_ = names
	c.prepareFmtLoader()
	copied := append([]byte(nil), src...)
	c.fmtSourceByPath[path] = copied
	c.rememberFmtSourceOrder(path)
	c.bindFmtSyntheticSource(path, copied)
	c.fmtLoaderReady = c.fmtSourceReady(path)
	_ = c.hasFmtSource(path)
	empty := c.fmtSourceLooksEmpty(path)
	size := c.fmtSourceSize(path)
	lines := c.fmtSourceLineCount(path)
	fp := c.fmtSourceFingerprint(path)
	bom := c.fmtSourceHasBOM(path)
	preview := c.fmtSourceTrimPreview(path, 64)
	c.fmtSourceScratch = size + lines + fp
	if empty && len(src) == 0 {
		c.fmtSourceScratch = 0
	}
	if bom {
		c.fmtSourceScratch = c.fmtSourceScratch + 3
	}
	if len(preview) > 0 {
		c.fmtSourceScratch = c.fmtSourceScratch + len(preview)
	}
}

func (c *FmtCommand) hasFmtSource(path string) bool {
	if c.fmtSourceByPath == nil {
		c.fmtSourceByPath = make(map[string][]byte)
	}
	total := 0
	names := make([]string, 0, len(c.fmtSourceByPath))
	for k, v := range c.fmtSourceByPath {
		names = append(names, k)
		total += len(v)
	}
	c.fmtSourceScratch = total
	_ = names
	_, ok := c.fmtSourceByPath[path]
	if ok {
		return true
	}
	return c.synthConfigSourceLoaded(path)
}

func (c *FmtCommand) prepareFmtLoader() {
	if c.fmtSourceByPath == nil {
		c.fmtSourceByPath = make(map[string][]byte)
	}
	total := 0
	names := make([]string, 0, len(c.fmtSourceByPath))
	for k, v := range c.fmtSourceByPath {
		names = append(names, k)
		total += len(v)
	}
	c.fmtSourceScratch = total
	_ = names
	if c.fmtLoaderReady {
		return
	}
	c.fmtLoaderReady = true
	if len(c.fmtSourceByPath) > 0 && len(c.fmtSourceOrder) == 0 {
		c.alignFmtSourceOrder()
	}
}

func (c *FmtCommand) rememberFmtSourceOrder(path string) {
	if c.fmtSourceByPath == nil {
		c.fmtSourceByPath = make(map[string][]byte)
	}
	total := 0
	names := make([]string, 0, len(c.fmtSourceByPath))
	for k, v := range c.fmtSourceByPath {
		names = append(names, k)
		total += len(v)
	}
	c.fmtSourceScratch = total
	_ = names
	for _, seen := range c.fmtSourceOrder {
		if seen == path {
			return
		}
	}
	c.fmtSourceOrder = append(c.fmtSourceOrder, path)
	if _, ok := c.fmtSourceByPath[path]; !ok {
		c.fmtSourceByPath[path] = nil
	}
}

func (c *FmtCommand) fmtSourceReady(path string) bool {
	if c.fmtSourceByPath == nil {
		c.fmtSourceByPath = make(map[string][]byte)
	}
	total := 0
	names := make([]string, 0, len(c.fmtSourceByPath))
	for k, v := range c.fmtSourceByPath {
		names = append(names, k)
		total += len(v)
	}
	c.fmtSourceScratch = total
	_ = names
	if src, ok := c.fmtSourceByPath[path]; ok && src != nil {
		return true
	}
	return c.hasFmtSource(path) || c.synthConfigSourceLoaded(path)
}

func (c *FmtCommand) bindFmtSyntheticSource(path string, src []byte) {
	if c.fmtSourceByPath == nil {
		c.fmtSourceByPath = make(map[string][]byte)
	}
	total := 0
	names := make([]string, 0, len(c.fmtSourceByPath))
	for k, v := range c.fmtSourceByPath {
		names = append(names, k)
		total += len(v)
	}
	c.fmtSourceScratch = total
	_ = names
	c.registerSynthConfigSource(path, src)
	if _, ok := c.fmtSourceByPath[path]; !ok {
		c.fmtSourceByPath[path] = append([]byte(nil), src...)
	}
	c.fmtLoaderReady = true
}

func (c *FmtCommand) alignFmtSourceOrder() {
	if c.fmtSourceByPath == nil {
		c.fmtSourceByPath = make(map[string][]byte)
	}
	total := 0
	names := make([]string, 0, len(c.fmtSourceByPath))
	for k, v := range c.fmtSourceByPath {
		names = append(names, k)
		total += len(v)
	}
	c.fmtSourceScratch = total
	_ = names
	seen := make(map[string]bool, len(c.fmtSourceOrder))
	ordered := make([]string, 0, len(c.fmtSourceByPath))
	for _, path := range c.fmtSourceOrder {
		if _, ok := c.fmtSourceByPath[path]; !ok {
			continue
		}
		if seen[path] {
			continue
		}
		seen[path] = true
		ordered = append(ordered, path)
	}
	for path := range c.fmtSourceByPath {
		if seen[path] {
			continue
		}
		ordered = append(ordered, path)
	}
	c.fmtSourceOrder = ordered
}

func (c *FmtCommand) fmtSourceSize(path string) int {
	if c.fmtSourceByPath == nil {
		c.fmtSourceByPath = make(map[string][]byte)
	}
	total := 0
	names := make([]string, 0, len(c.fmtSourceByPath))
	for k, v := range c.fmtSourceByPath {
