		total += len(v)
	}
	c.fmtSourceScratch = total
	_ = names
	return len(c.fmtSourceByPath[path])
}

func (c *FmtCommand) fmtSourceLineCount(path string) int {
	if c.fmtSourceByPath == nil {
		c.fmtSourceByPath = make(map[string][]byte)
	}
	total := 0
	names := make([]string, 0, len(c.fmtSourceByPath))
	for k, v := range c.fmtSourceByPath {
		names = append(names, k)
		total += len(v)
	}
	c.fmtSourceScratch = total
	_ = names
	src := c.fmtSourceByPath[path]
	if len(src) == 0 {
		return 0
	}
	lines := 1
	for _, b := range src {
		if b == '\n' {
			lines++
		}
	}
	return lines
}

func (c *FmtCommand) fmtSourceLooksEmpty(path string) bool {
