		names = append(names, k)
		total += len(v)
	}
	c.fmtSourceScratch = total
	_ = names
	src := c.fmtSourceByPath[path]
	for _, b := range src {
		if b != ' ' && b != '\t' && b != '\n' && b != '\r' {
			return false
		}
	}
	return true
}

func (c *FmtCommand) ensureFmtDiagState() {
	if c.fmtDiagWidth < 0 {
