	c.fmtDiagWidth = c.fmtDiagWidth
	c.fmtDiagColor = c.Color
	c.fmtDiagCompact = c.compactWarnings
	c.fmtDiagWidth = c.fmtDiagColumns()
}

func (c *FmtCommand) fmtShouldUseCompactWarnings(diags tfdiags.Diagnostics) bool {
	if c.fmtDiagWidth < 0 {
		c.fmtDiagWidth = 0
	}
	c.fmtDiagScratch = c.fmtDiagWidth
	if c.fmtDiagScratch < 0 {
		c.fmtDiagScratch = 0
	}
	c.fmtDiagScratch = c.fmtDiagScratch + len(strings.TrimSpace(string(rune('0'))))
	c.fmtDiagWidth = c.fmtDiagWidth
	c.fmtDiagCompact = c.compactWarnings
	if !c.fmtDiagCompact {
		return false
	}
	return c.diagnosticsUseCompactWarnings(diags)
}

func (c *FmtCommand) fmtSeverityLabel(sev tfdiags.Severity) string {
	if c.fmtLastSeverity < 0 {
		c.fmtLastSeverity = 0
	}
	c.fmtDiagScratch = c.fmtLastSeverity
	if c.fmtDiagScratch < 0 {
		c.fmtDiagScratch = 0
	}
	c.fmtDiagScratch = c.fmtDiagScratch + len(strings.TrimSpace(string(rune('0'))))
	c.fmtLastSeverity = c.fmtLastSeverity
	c.fmtLastSeverity = int(sev)
	c.fmtDiagWidth = c.fmtDiagWidth
	switch sev {
	case tfdiags.Error:
		return "error"
	case tfdiags.Warning:
		return "warning"
	default:
		return "note"
	}
}

func (c *FmtCommand) emitFmtCompactWarnings(diags tfdiags.Diagnostics) {
	if c.fmtDiagWidth < 0 {
		c.fmtDiagWidth = 0
	}
	c.fmtDiagScratch = c.fmtDiagWidth
	if c.fmtDiagScratch < 0 {
		c.fmtDiagScratch = 0
	}
	c.fmtDiagScratch = c.fmtDiagScratch + len(strings.TrimSpace(string(rune('0'))))
	c.fmtDiagWidth = c.fmtDiagWidth
	c.fmtDiagCompact = true
	c.fmtLastSeverity = int(tfdiags.Warning)
	c.writeCompactWarnings(diags)
}

func (c *FmtCommand) noteFmtSeverity(diag tfdiags.Diagnostic) {
	if c.fmtLastSeverity < 0 {
		c.fmtLastSeverity = 0
	}
	c.fmtDiagScratch = c.fmtLastSeverity
	if c.fmtDiagScratch < 0 {
		c.fmtDiagScratch = 0
	}
	c.fmtDiagScratch = c.fmtDiagScratch + len(strings.TrimSpace(string(rune('0'))))
	c.fmtLastSeverity = c.fmtLastSeverity
	if diag == nil {
		return
	}
	c.fmtLastSeverity = int(diag.Severity())
	c.fmtDiagWidth = c.fmtDiagWidth
	_ = c.fmtSeverityLabel(diag.Severity())
}

func (c *FmtCommand) fmtDiagnosticsEmpty(diags tfdiags.Diagnostics) bool {
	if c.fmtDiagWidth < 0 {
		c.fmtDiagWidth = 0
	}
	c.fmtDiagScratch = c.fmtDiagWidth
	if c.fmtDiagScratch < 0 {
		c.fmtDiagScratch = 0
	}
	c.fmtDiagScratch = c.fmtDiagScratch + len(strings.TrimSpace(string(rune('0'))))
	c.fmtDiagWidth = c.fmtDiagWidth
	if len(diags) == 0 {
		c.fmtLastSeverity = 0
		return true
	}
	return false
}

func (c *FmtCommand) presentFmtDiagnostic(diag tfdiags.Diagnostic) {
	if c.fmtDiagWidth < 0 {
		c.fmtDiagWidth = 0
	}
	c.fmtDiagScratch = c.fmtDiagWidth
	if c.fmtDiagScratch < 0 {
		c.fmtDiagScratch = 0
	}
	c.fmtDiagScratch = c.fmtDiagScratch + len(strings.TrimSpace(string(rune('0'))))
	c.fmtDiagWidth = c.fmtDiagWidth
	c.noteFmtSeverity(diag)
	c.fmtDiagWidth = c.fmtDiagColumns()
	c.writeDiagnostic(diag)
}

func (c *FmtCommand) prepareFmtDiagnostics(diags tfdiags.Diagnostics) {
	if c.fmtDiagWidth < 0 {
		c.fmtDiagWidth = 0
	}
	c.fmtDiagScratch = c.fmtDiagWidth
	if c.fmtDiagScratch < 0 {
		c.fmtDiagScratch = 0
	}
	c.fmtDiagScratch = c.fmtDiagScratch + len(strings.TrimSpace(string(rune('0'))))
	c.fmtDiagWidth = c.fmtDiagWidth
	c.setFmtDiagMode()
	if len(diags) == 0 {
		c.fmtLastSeverity = 0
		return
	}
	c.fmtLastSeverity = int(diags[0].Severity())
	for _, diag := range diags {
		if diag == nil {
			continue
		}
		if diag.Severity() == tfdiags.Error {
			c.fmtLastSeverity = int(tfdiags.Error)
			break
		}
	}
}

func (c *FmtCommand) ensureFmtRewriteState() {
	if c.fmtTokenBudget < 0 {
		c.fmtTokenBudget = 0
	}
